420		t.Run("same hash different txs", func(t *testing.T) {
421			index, cursor := build(t)
422			// The block keeps its hash but its transaction content changes.
423			if _, err := index.Reorg([]Block{
424				{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"z"}},
425				{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"c"}},
426			}); err != nil {
427				t.Fatal(err)
428			}
429			if _, err := index.QueryTxs(TxQuery{Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
430				t.Fatalf("err=%v, want ErrQueryChanged", err)
431			}
432		})
433	
434		t.Run("chain shortened", func(t *testing.T) {
435			index, cursor := build(t)
436			if _, err := index.Reorg([]Block{{Height: 2, Hash: "h2b", Parent: "h1"}}); err != nil {
437				t.Fatal(err)
438			}
439			if _, err := index.QueryTxs(TxQuery{Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
440				t.Fatalf("err=%v, want ErrQueryChanged", err)
441			}
442		})
443	
444		t.Run("index stays usable", func(t *testing.T) {
445			index, cursor := build(t)
446			if _, err := index.Reorg([]Block{{Height: 2, Hash: "h2b", Parent: "h1"}}); err != nil {
447				t.Fatal(err)
448			}
449			if _, err := index.QueryTxs(TxQuery{Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
450				t.Fatalf("err=%v, want ErrQueryChanged", err)
451			}
452			// A fresh first-page query against the new chain state works.
453			page, err := index.QueryTxs(TxQuery{})
454			if err != nil {
455				t.Fatalf("fresh query after reorg failed: %v", err)
456			}
457			if page.ToHeight != 2 || page.TotalMatches != 1 {
458				t.Fatalf("unexpected fresh page: %+v", page)
459			}
460		})
461	}
462	
463	func TestQueryTxsRejectsBadCursors(t *testing.T) {
464		index := txChain(t, []string{"a"}, []string{"b"})
465		first, err := index.QueryTxs(TxQuery{PageSize: 1})
466		if err != nil {
467			t.Fatal(err)
468		}
469		good := first.NextCursor
470		if good == "" {
471			t.Fatal("expected a continuation cursor")
472		}
473	
474		tampered := []byte(good)
475		mid := len(tampered) / 2
476		if tampered[mid] == 'A' {
477			tampered[mid] = 'B'
478		} else {
479			tampered[mid] = 'A'
480		}
481		for name, cursor := range map[string]string{
482			"garbage":   "not-a-cursor",
483			"truncated": good[:len(good)-2],
484			"tampered":  string(tampered),
485		} {
486			if _, err := index.QueryTxs(TxQuery{Cursor: cursor}); !errors.Is(err, ErrInvalidArgument) {
487				t.Errorf("%s: err=%v, want ErrInvalidArgument", name, err)
488			}
489		}
490	
491		// A cursor minted by another index instance is an argument error, even
492		// when the other index holds identical data.
493		other := txChain(t, []string{"a"}, []string{"b"})
494		if _, err := other.QueryTxs(TxQuery{Cursor: good}); !errors.Is(err, ErrInvalidArgument) {
495			t.Fatalf("foreign cursor: err=%v, want ErrInvalidArgument", err)
496		}
497	
498		// None of the failures invalidated the genuine cursor.
499		if _, err := index.QueryTxs(TxQuery{Cursor: good}); err != nil {
500			t.Fatalf("valid cursor refused after rejected ones: %v", err)
501		}
502	}
503	
504	func TestQueryTxsSameCursorSamePage(t *testing.T) {
505		index := txChain(t,
506			[]string{"a"},
507			[]string{"b"},
508			[]string{"c"},
509		)
510		first, err := index.QueryTxs(TxQuery{PageSize: 1})
511		if err != nil {
512			t.Fatal(err)
513		}
514		pageA, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor})
515		if err != nil {
516			t.Fatal(err)
517		}
518		pageB, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor})
519		if err != nil {
520			t.Fatal(err)
521		}
522		if !reflect.DeepEqual(pageA, pageB) {
523			t.Fatalf("repeated cursor returned different pages:\n%+v\n%+v", pageA, pageB)
524		}
525	}
526	
527	func TestQueryTxsReturnedHitsAreCopies(t *testing.T) {
528		index := txChain(t, []string{"a", "b"})
529		page, err := index.QueryTxs(TxQuery{})
530		if err != nil {
531			t.Fatal(err)
532		}
533		page.Hits[0].TxID = "mutated"
534		page.Hits[0].BlockHash = "mutated"
535		page.Hits[0].Height = 99
536		again, err := index.QueryTxs(TxQuery{})
537		if err != nil {
538			t.Fatal(err)
539		}
540		want := TxHit{Height: 1, BlockHash: "h1", TxID: "a", Position: 0}
541		if again.Hits[0] != want {
542			t.Fatalf("caller mutation leaked into the index: %+v", again.Hits[0])
543		}
544	}
545	
546	func TestQueryTxsDoesNotMutateIndex(t *testing.T) {
547		index := txChain(t,
548			[]string{"a", "b"},
549			[]string{"c"},
550		)
551		blocks, byHash, tip := snapshot(index)
552		for _, page := range collectPages(t, index, TxQuery{PageSize: 1}) {
553			_ = page
554		}
555		requireUnchanged(t, index, blocks, byHash, tip)
556	}
557	
558	func TestQueryTxsConcurrentWithAppends(t *testing.T) {
559		index := chain(t, Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"tx-1"}})
560		stop := make(chan struct{})
561	
562		var writer sync.WaitGroup
563		writer.Add(1)
564		go func() {
565			defer writer.Done()
566			for height := int64(2); height <= 200; height++ {
567				select {
568				case <-stop:
569					return
570				default:
571				}
572				block := Block{
573					Height: height,
574					Hash:   fmt.Sprintf("h%d", height),
575					Parent: fmt.Sprintf("h%d", height-1),
576					Txs:    []string{fmt.Sprintf("tx-%d", height)},
577				}
578				if err := index.Append(block); err != nil {
579					return
580				}
581			}
582		}()
583	
584		var readers sync.WaitGroup
585		for reader := 0; reader < 4; reader++ {
586			readers.Add(1)
587			go func() {
588				defer readers.Done()
589				for round := 0; round < 20; round++ {
590					// Appends above the pinned range never invalidate a query,
591					// so every pagination run must complete and stay consistent.
592					pages := 0
593					seen := 0
594					var total, matched, to int64 = -1, -1, -1
595					query := TxQuery{PageSize: 7}
596					var lastHeight int64
597					var lastPosition = -1
598					for {
599						page, err := index.QueryTxs(query)
600						if err != nil {
601							t.Errorf("query failed during appends: %v", err)
602							return
603						}
604						if total == -1 {
605							total, matched, to = page.TotalMatches, page.MatchedBlocks, page.ToHeight
606						} else if page.TotalMatches != total || page.MatchedBlocks != matched || page.ToHeight != to {
607							t.Errorf("stats changed mid-pagination: %+v", page)
608							return
609						}
610						for _, hit := range page.Hits {
611							if hit.Height < lastHeight || (hit.Height == lastHeight && hit.Position <= lastPosition) {
612								t.Errorf("hits out of order after (%d,%d): %+v", lastHeight, lastPosition, hit)
613								return
614							}
615							if hit.Height > page.ToHeight {
616								t.Errorf("hit above pinned bound: %+v vs %d", hit, page.ToHeight)
617								return
618							}
619							lastHeight, lastPosition = hit.Height, hit.Position
620						}
621						seen += len(page.Hits)
622						pages++
623						if page.NextCursor == "" {
624							break
625						}
626						query.Cursor = page.NextCursor
627					}
628					if int64(seen) != total {
629						t.Errorf("paginated %d hits over %d pages, total says %d", seen, pages, total)
630						return
631					}
632				}
633			}()
634		}
635		readers.Wait()
636		close(stop)
637		writer.Wait()
638	}
